from taf.ul.ettf.sim.core.parser import Parser
from taf.ul.ettf.utils.exception import LibraryError


class NoColumnException(LibraryError):
    pass


class NoRowException(LibraryError):
    pass


class NotParsedYetException(LibraryError):
    pass


class NoDataException(LibraryError):
    pass


class GenericParser(Parser):
    DATA_END = '=' * 10
    COLUMN_NAMES_LIE_AHEAD = '-' * 10

    def __init__(self):
        self._values_table = None
        self._column_names = None
        self._row_names = None

    def parse(self, raw_table):
        table = self._raw_table_converted_to_rows(raw_table)
        self._column_names = self._parse_column_names(table)
        self._row_names = self._parse_row_names(table)
        self._values_table = self._parse_values_tables(table)
        return self

    def _raw_table_converted_to_rows(self, raw_table):
        return self._remove_empty_lines(self._split_to_lines(raw_table))

    @staticmethod
    def _split_to_lines(raw_table):
        return raw_table.replace('\r', '').split('\n')

    @staticmethod
    def _remove_empty_lines(lines):
        return [line for line in lines if line.strip() != '']

    def get_value(self, column_name, row_name=None):
        if not self._values_table:
            raise NotParsedYetException('Parser does not have parsed table',
                                        'Please parse command output before accessing it\'s members')

        column_index = self._get_column_index(column_name)
        row_index = self._get_row_index(row_name)
        return self._values_table[row_index][column_index]

    def _get_row_index(self, row_name):
        try:
            return self._row_names.index(row_name) if row_name else 0
        except ValueError:
            raise NoRowException('Row name \'{}\' not found'.format(row_name),
                                 'Provide correct row name')

    def _get_column_index(self, column_name):
        try:
            return self._column_names.index(column_name)
        except ValueError:
            raise NoColumnException('Column name \'{}\' not found'.format(column_name),
                                    'Provide correct column name')

    def _parse_column_names(self, table):
        for index, row in enumerate(table[1:]):
            if row.strip().startswith(self.COLUMN_NAMES_LIE_AHEAD):
                raw_column_names = table[index].split('  ')
                return [raw_column_name.strip() for raw_column_name in raw_column_names if raw_column_name.strip()]

    def _parse_row_names(self, table):
        data_start_index, data_end_index = self._get_data_edges(table)
        row_names = []
        for row in table[data_start_index:data_end_index]:
            first_element_of_the_row = row.split('  ')[0]
            if first_element_of_the_row[0].isdigit():
                continue
            row_names.append(first_element_of_the_row)
        return row_names

    def _get_data_edges(self, table):
        start_index, end_index = None, None
        for index, row in enumerate(table):
            if start_index is None and row.strip().startswith(self.COLUMN_NAMES_LIE_AHEAD):
                start_index = index + 1
            if start_index is not None and not row.strip().startswith(self.DATA_END):
                end_index = index + 1
            if end_index is not None and row.strip().startswith(self.DATA_END):
                return start_index, end_index
        raise NoDataException('Parser could not map edges of the table',
                              'Please provide valid command output')

    def _parse_values_tables(self, table):
        values_rows = self._get_values_rows(table)
        return self._get_values_table(values_rows)

    def _get_values_rows(self, table):
        values_rows = []
        read = False
        for row in table:
            if read and not row.strip().startswith(self.DATA_END):
                values_rows.append(row)
            if read and row.strip().startswith(self.DATA_END):
                break
            if row.strip().startswith(self.COLUMN_NAMES_LIE_AHEAD):
                read = True
        return values_rows

    def _get_values_table(self, values_rows):
        values_table = []
        for values_row in values_rows:
            raw_separated_values = values_row.split('  ')
            separated_values = [separated_value.strip() for separated_value in raw_separated_values
                                if separated_value.strip()]
            values_table.append(separated_values)
        return values_table
